/* UI shell generated from the observed native Design hierarchy, not from the old 68-tool mock. */
(()=>{'use strict';
const ref=window.asaFusionNativeReference,ru=window.asaFusionRussianLabels,art=window.asaNativeIcon;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=name=>{if(!Object.hasOwn(ru,name))throw Error('Missing Russian UI label: '+name);return ru[name];};
const command=id=>ref.commands[id],label=id=>tr(command(id).name);
let tabId='SolidTab',opener=null,menus=[],tipTimer=0,detailTimer=0,hoverItem=null;
const root=document.getElementById('app');root.dataset.nativeReferenceVersion=ref.applicationVersion;
const tip=document.createElement('aside');tip.id='nativeTooltip';tip.className='native-tooltip';tip.setAttribute('role','tooltip');document.body.append(tip);
const descriptions={
 SketchCreate:'Выберите плоскость или плоскую грань, чтобы начать построение эскиза.',Extrude:'Создаёт объём или вырез по выбранным профилям. Начало, направление, протяжённость и операция задаются отдельно.',Revolve:'Выберите профиль и ось вращения. Затем задайте угол и тип операции.',FusionHoleCommand:'Выберите грань или точки эскиза. Настройте форму отверстия, резьбу и вершину сверла.',
 AutomatedModelingCommand:'Выберите соединяемые грани и тела, которые необходимо обойти. Команда предлагает варианты формы детали.',FusionSplitBodyCommand:'Выберите разделяемое тело и инструмент разделения. При необходимости продлите инструмент.',PatternRectangular:'Выберите тип объектов, сами объекты и направления прямоугольного массива.',FusionPressPullCommand:'Выберите геометрию для изменения формы или размера.',FusionFilletEdgesCommand:'Задайте тип скругления, набор рёбер или граней, радиус и тип углового сопряжения.',FusionShellBodyCommand:'Выберите грани или тело для создания тонкостенной оболочки.',FusionCombineCommand:'Выберите целевое тело и тела-инструменты. Доступны объединение, вычитание и пересечение.',FusionMoveCommand:'Перемещает или копирует выбранные объекты. Способ перемещения выбирается в панели.',ConstructionPlaneOffsetFromPlaneCommand:'Выберите исходную плоскость или плоскую грань для построения смещённой плоскости.',MeasureCommand:'Показывает размеры и взаимное положение выбранной геометрии.',PullDeriveCommand:'Вставляет производную геометрию из другого документа.',NewAssemblyFromPartCommand:'Добавляет текущую деталь в сборку. Требуется сохранённый документ.'};
function clearTip(){clearTimeout(tipTimer);clearTimeout(detailTimer);tip.hidden=true;hoverItem=null;}
function place(box,rect,side=false){box.style.left='0px';box.style.top='0px';const b=box.getBoundingClientRect();let x=side?rect.right+1:rect.left,y=side?rect.top:rect.bottom+2;if(x+b.width>innerWidth-6)x=side?rect.left-b.width-1:innerWidth-b.width-6;if(y+b.height>innerHeight-6)y=innerHeight-b.height-6;box.style.left=Math.max(4,x)+'px';box.style.top=Math.max(4,y)+'px';}
function tooltip(el){clearTip();const id=el.dataset.nativeCommand;if(!id||!command(id))return;hoverItem=el;
 tipTimer=setTimeout(()=>{if(hoverItem!==el)return;tip.classList.remove('expanded');tip.innerHTML='<strong>'+esc(label(id))+'</strong>';tip.hidden=false;place(tip,el.getBoundingClientRect());},600);
 detailTimer=setTimeout(()=>{if(hoverItem!==el)return;tip.classList.add('expanded');tip.innerHTML='<strong>'+esc(label(id))+'</strong><p>'+esc(descriptions[id]||'Команда есть в каталоге оригинала. Подробные состояния этого окна ещё проходят проверку.')+'</p><div class="native-tooltip-art">'+art.draw(id,88)+'</div><small>Собственная иллюстрация · сверка внешнего вида не завершена</small>';tip.hidden=false;place(tip,el.getBoundingClientRect());},2000);
}
function closeMenus(from=0,restore=false){for(const m of menus.splice(from))m.remove();if(from===0){document.querySelectorAll('[data-native-group]').forEach(b=>b.setAttribute('aria-expanded','false'));if(restore)opener?.focus();opener=null;}clearTip();}
function rows(list){return list.map((c,i)=>{if(c.kind==='SeparatorControl')return '<div class="native-menu-sep" role="separator"></div>';const id=c.commandId,child=c.children,nm=id?label(id):tr(c.name);const hot={Extrude:'E',FusionHoleCommand:'H',FusionPressPullCommand:'Q',FusionFilletEdgesCommand:'F',FusionMoveCommand:'M',MeasureCommand:'I'}[id]||'';return `<button type="button" class="native-menu-item" role="menuitem" data-native-row="${i}" ${id?`data-native-command="${esc(id)}"`:''} ${child?'aria-haspopup="menu"':''} ${c.enabled===false?'disabled aria-disabled="true"':''}><span class="native-menu-icon">${id?art.draw(id,20):''}</span><span class="native-menu-text">${esc(nm)}</span><span class="native-menu-key">${child?'›':hot}</span></button>`;}).join('');}
function makeMenu(list,anchor,level=0){closeMenus(level);const box=document.createElement('div');box.className='native-menu';box.setAttribute('role','menu');box.dataset.level=String(level);box.innerHTML=rows(list);document.body.append(box);menus.push(box);place(box,anchor.getBoundingClientRect(),level>0);
 box.addEventListener('pointerover',e=>{const row=e.target.closest('[data-native-row]');if(!row)return;const item=list[+row.dataset.nativeRow];if(item.children){if(menus[level+1]?.dataset.parent===item.id)return;makeMenu(item.children,row,level+1);menus[level+1].dataset.parent=item.id;}else{closeMenus(level+1);tooltip(row);}});
 box.addEventListener('click',e=>{const row=e.target.closest('[data-native-row]');if(!row)return;e.stopPropagation();const item=list[+row.dataset.nativeRow];if(item.children){makeMenu(item.children,row,level+1);menus[level+1].querySelector('button')?.focus();}else if(item.enabled!==false){run(item.commandId);}});
 box.addEventListener('keydown',e=>{const buttons=[...box.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();e.stopPropagation();const n=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowUp'?-1:1)+buttons.length)%buttons.length;buttons[n]?.focus();}else if(e.key==='ArrowRight'){const row=document.activeElement,item=list[+row?.dataset.nativeRow];if(item?.children){e.preventDefault();makeMenu(item.children,row,level+1);menus[level+1].querySelector('button')?.focus();}}else if(e.key==='ArrowLeft'&&level){e.preventDefault();closeMenus(level);anchor.focus();}});
 box.addEventListener('focusin',e=>{const r=e.target.closest('[data-native-command]');if(r)tooltip(r);});return box;
}
function render(){const current=ref.tabs.find(t=>t.id===tabId);document.getElementById('tabs').innerHTML=ref.tabs.map(t=>`<button type="button" role="tab" class="tab ${t.id===tabId?'active':''}" data-native-tab="${t.id}" aria-selected="${t.id===tabId}">${esc(tr(t.name).toLocaleUpperCase('ru'))}</button>`).join('');
 document.getElementById('groups').innerHTML=current.panels.map(pid=>{const p=ref.panels[pid],title=tr(p.name);return `<section class="rgroup native-ribbon-group" data-native-panel="${pid}" aria-label="${esc(title)}"><div class="toolrow">${p.promoted.map(c=>{const id=c.commandId;return `<button type="button" class="toolbtn native-tool" data-native-command="${esc(id)}" aria-label="${esc(label(id))}" ${c.enabled===false?'disabled aria-disabled="true"':''}>${art.draw(id,39)}</button>`;}).join('')}</div><button class="groupLabel native-group-trigger" type="button" data-native-group="${pid}" aria-haspopup="menu" aria-expanded="false">${esc(title)}<span class="arr">⌄</span></button></section>`;}).join('');root.dataset.nativeTab=tabId;root.dataset.nativeVisibleButtons=String(current.panels.reduce((s,p)=>s+ref.panels[p].promoted.length,0));
}
function switchTab(id){const t=ref.tabs.find(x=>x.id===id||tr(x.name).toLocaleUpperCase('ru')===String(id).toLocaleUpperCase('ru'));if(!t)throw Error('Unknown native tab '+id);closeMenus();tabId=t.id;activeTab=tr(t.name).toLocaleUpperCase('ru');render();}
function run(id){const d=command(id);if(!d||d.enabled===false)return;closeMenus();clearTip();document.querySelectorAll('.native-tool').forEach(b=>b.classList.toggle('selected',b.dataset.nativeCommand===id));window.dispatchEvent(new CustomEvent('asa-cad:native-ui-request',{detail:{nativeCommandId:id,locale:'ru',referenceOnly:true}}));window.asaNativeDialogs?.open(id);}
function choose(anchor,title,options,value,changed,optionArt=null){closeMenus();const list=options.map((name,i)=>({id:'choice-'+i,kind:'choice',name}));const box=document.createElement('div');box.className='native-menu native-field-menu';box.setAttribute('role','listbox');box.setAttribute('aria-label',title);box.innerHTML=options.map((s,i)=>`<button type="button" role="option" aria-selected="${s===value}" data-choice="${i}"><span>${optionArt?optionArt(s):(s===value?'✓':'')}</span>${esc(s)}</button>`).join('');document.body.append(box);menus.push(box);place(box,anchor.getBoundingClientRect());box.addEventListener('click',e=>{const b=e.target.closest('[data-choice]');if(b){e.stopPropagation();changed(options[+b.dataset.choice]);closeMenus();anchor.focus();}});const bs=[...box.querySelectorAll('button')];bs.find(b=>b.getAttribute('aria-selected')==='true')?.focus();box.addEventListener('keydown',e=>{let n=bs.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();bs[(n+(e.key==='ArrowDown'?1:-1)+bs.length)%bs.length].focus();}});}
document.addEventListener('click',e=>{const t=e.target.closest('button[data-native-tab]');if(t){e.stopImmediatePropagation();switchTab(t.dataset.nativeTab);return;}const g=e.target.closest('[data-native-group]');if(g){e.stopImmediatePropagation();if(opener===g&&menus.length){closeMenus();return;}closeMenus();opener=g;makeMenu(ref.panels[g.dataset.nativeGroup].menu,g);opener=g;g.setAttribute('aria-expanded','true');return;}const c=e.target.closest('.native-tool');if(c){e.stopImmediatePropagation();if(!c.disabled)run(c.dataset.nativeCommand);return;}if(!e.target.closest('.native-menu,.native-tooltip,[data-native-field]'))closeMenus();},true);
document.addEventListener('pointerover',e=>{const el=e.target.closest('.native-tool');if(el)tooltip(el);});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-native-command]')&&!e.relatedTarget?.closest?.('.native-tooltip'))clearTip();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenus(0,true);window.asaNativeDialogs?.close();}if(!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest('input,textarea,[contenteditable],select')&&!window.asaNativeDialogs?.isOpen()){const id={e:'Extrude',h:'FusionHoleCommand',q:'FusionPressPullCommand',f:'FusionFilletEdgesCommand',m:'FusionMoveCommand',i:'MeasureCommand'}[e.key.toLowerCase()];if(id){e.preventDefault();run(id);}}},true);
window.addEventListener('resize',()=>{closeMenus();window.asaNativeDialogs?.clamp();});
window.asaNativeUI={ref,tr,label,run,switchTab,choose,closeMenus,getTab:()=>tabId,getState:()=>({tabId,commands:Object.keys(ref.commands).length,menus:menus.length,kernelConnected:false})};
window.asaCad.setActiveTab=switchTab;window.setActiveTab=switchTab;window.renderRibbon=render;render();tip.hidden=true;
})();
